"""Offline coefficient generator; not a build/runtime dependency.

Run with SciPy 1.13.1 + NumPy 2.0.2 in build/filter-venv. Search odd-length
Type-I minimax FIRs, preserving integer sample centres. Quantize to float32,
then verify on a dense grid (including band endpoints). The 5e-6 design bound
leaves 6 dB for modulation/accumulation before the 100 dB runtime requirement.
"""

import pathlib

import numpy as np
from scipy.signal import freqz, remez

root = pathlib.Path(__file__).resolve().parents[1]
lines = [
    "// Generated by scripts/design_channel_filter.py; do not edit.",
    "// Pass: 0..3.328125 MHz, stop: 3.671875 MHz..Nyquist, |error| <= 5e-6.",
    "#pragma once",
    "#include <array>",
    "#include <span>",
    "#include <stdexcept>",
    "namespace radar::filters {",
]


def candidate(half, fs):
    for density in (48, 32, 64, 16, 96):
        try:
            h = remez(
                2 * half + 1,
                [0, 3328125, 3671875, fs / 2],
                [1, 0],
                fs=fs,
                maxiter=100,
                grid_density=density,
            ).astype(np.float32)
            break
        except ValueError:
            if density == 96:
                raise
    f, response = freqz(h.astype(float), worN=2**19, fs=fs)
    edge = freqz(h.astype(float), worN=[3328125, 3671875, fs / 2], fs=fs)[1]
    ripple = max(np.max(np.abs(np.abs(response[f <= 3328125]) - 1)), abs(abs(edge[0]) - 1))
    stop = max(np.max(np.abs(response[f >= 3671875])), max(abs(edge[1:])))
    return h, ripple, stop


for decimation in range(1, 9):
    fs = decimation * 8e6
    lo, hi = 50 * decimation, 100 * decimation
    while lo < hi:
        mid = (lo + hi) // 2
        _, ripple, stop = candidate(mid, fs)
        if max(ripple, stop) <= 5e-6:
            hi = mid
        else:
            lo = mid + 1
    h, ripple, stop = candidate(lo, fs)
    _, previous_ripple, previous_stop = candidate(lo - 1, fs)
    assert max(ripple, stop) <= 5e-6 < max(previous_ripple, previous_stop)
    print(
        f"{fs / 1e6:g} MS/s: {len(h)} taps, ripple {ripple:.9g}, stop {20 * np.log10(stop):.4f} dB; "
        f"{len(h) - 2} taps error {max(previous_ripple, previous_stop):.9g}",
        flush=True,
    )
    lines += [
        f"// ripple={ripple:.9g}, stop={20 * np.log10(stop):.4f} dB",
        f"inline constexpr std::array<float,{len(h)}> decimate_{decimation} = {{",
    ]
    for i in range(0, len(h), 6):
        lines.append("    " + ", ".join(f"{float(x):.9e}F" for x in h[i : i + 6]) + ",")
    lines.append("};")
lines += [
    "inline std::span<const float> prototype(unsigned decimation) {",
    "    switch(decimation) {",
]
for decimation in range(1, 9):
    lines.append(f"    case {decimation}: return decimate_{decimation};")
lines += [
    '    default: throw std::runtime_error("No prototype for this decimation");',
    "    }",
    "}",
    "}",
]
(root / "src/channel_filters.hpp").write_text("\n".join(lines) + "\n")
